package com.sakti.banking.controller; import com.sakti.banking.dto.ServiceRequestRequest; import com.sakti.banking.entity.ServiceRequest; import com.sakti.banking.service.ServiceRequestService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/service-requests") public class ServiceRequestController {private final ServiceRequestService svc;public ServiceRequestController(ServiceRequestService s){svc=s;} @PostMapping public ServiceRequest create(Authentication a,@Valid @RequestBody ServiceRequestRequest r){return svc.create(a.getName(),r);} @GetMapping public List<ServiceRequest> mine(Authentication a){return svc.mine(a.getName());}}
